import test from 'node:test';
import assert from 'node:assert/strict';
import { DatabaseSync } from 'node:sqlite';
import { readFileSync, readdirSync } from 'node:fs';
import { makeHandler, parseTranscription } from '../lib/writeon-api.ts';

// A complete 2x2 white JPEG, generated by Pillow. No personal data or live keys.
const JPEG = '';
const photo = { image: JPEG, mimeType: 'image/jpeg' };
const GEMINI = { 'x-gemini-key': 'test-only-gemini-key' };
const ELEVEN = { 'x-elevenlabs-key': 'test-only-eleven-key' };
const ORIGIN = 'https://writeon.test';

function candidate(result = { text: 'Hello [unclear]', uncertain: true, notes: 'One word is unclear.' }) {
 return { candidates: [{ finishReason: 'STOP', content: { parts: [{ thought: true, text: 'Private reasoning should be ignored.' }, { text: JSON.stringify(result) }] } }] };
}
function setup(t, { upstream, initialTime = 1_800_000_000_000, env = {} } = {}) {
 const sqlite = new DatabaseSync(':memory:');
 const migrations = readdirSync(new URL('../drizzle/', import.meta.url)).filter(n => n.endsWith('.sql')).sort();
 for (const file of migrations) sqlite.exec(readFileSync(new URL(`../drizzle/${file}`, import.meta.url), 'utf8'));
 t.after(() => sqlite.close());
 function prepare(sql, parameters = []) {
  return {
   bind(...args) { return prepare(sql, args); },
   async first() { return sqlite.prepare(sql).get(...parameters) ?? null; },
   async run() { const result = sqlite.prepare(sql).run(...parameters); return { success: true, meta: { changes: Number(result.changes) } }; },
  };
 }
 const DB = { prepare, async batch(queries) {
  sqlite.exec('BEGIN');
  try { const result = []; for (const query of queries) result.push(await query.run()); sqlite.exec('COMMIT'); return result; }
  catch (error) { sqlite.exec('ROLLBACK'); throw error; }
 } };
 let time = initialTime;
 let fetcher = upstream || (async () => { throw new Error('Unexpected network request in test'); });
 const handle = makeHandler({ DB, ...env }, { now: () => time, fetch: (...args) => fetcher(...args) });
 async function call(path, { method = 'GET', user = 'owner-a', input, headers = {} } = {}) {
  const h = { ...(user ? { 'oai-authenticated-user-id': user } : {}), ...headers };
  if (input !== undefined) h['content-type'] = 'application/json';
  return handle(new Request(`${ORIGIN}/api/${path}`, { method, headers: h, ...(input !== undefined ? { body: JSON.stringify(input) } : {}) }));
 }
 async function create() { const response = await call('rooms', { method: 'POST', input: {} }); assert.equal(response.status, 201); return response.json(); }
 async function upload(id) { const response = await call(`rooms/${id}/upload`, { method: 'POST', input: photo }); assert.equal(response.status, 200); return response.json(); }
 return { sqlite, call, create, upload, setTime: value => { time = value; }, advance: delta => { time += delta; }, setFetch: f => { fetcher = f; }, initialTime };
}

test('private endpoints require identity, isolate owners, and reject cross-site mutations', async t => {
 const s = setup(t);
 assert.equal((await s.call('rooms', { method: 'POST', user: null, input: {} })).status, 401);
 assert.equal((await s.call('rooms', { method: 'POST', input: {}, headers: { origin: 'https://evil.test' } })).status, 403);
 assert.equal((await s.call('rooms', { method: 'POST', input: {}, headers: { 'sec-fetch-site': 'cross-site' } })).status, 403);
 const room = await s.create();
 assert.equal((await s.call(`rooms/${room.id}`, { user: 'owner-b' })).status, 404);
 assert.equal((await s.call(`rooms/${room.id}/upload`, { method: 'POST', user: 'owner-b', input: photo })).status, 404);
 const row = s.sqlite.prepare('SELECT * FROM writeon_rooms').get();
 assert.notEqual(row.token_hash, room.token);
 assert.equal(row.token_hash.length, 64);
 const visible = await (await s.call(`rooms/${room.id}`)).json();
 assert.equal('owner' in visible, false); assert.equal('tokenHash' in visible, false);
});

test('phone pairing, remote capture and JPEG transfer survive the real SQLite update sequence', async t => {
 const s = setup(t), room = await s.create(), route = `rooms/${room.id}`;
 assert.equal((await s.call(`${route}/phone`, { method: 'POST', input: { ready: true } })).status, 403);
 assert.equal((await s.call(`${route}/phone`, { method: 'POST', input: { ready: true }, headers: { 'x-phone-token': 'wrong' } })).status, 403);
 const phone = { 'x-phone-token': room.token };
 let poll = await (await s.call(`${route}/phone`, { method: 'POST', input: { ready: true }, headers: phone })).json();
 assert.deepEqual(poll, { captureSeq: 0, frameSeq: 0 });
 const capture = await (await s.call(`${route}/capture`, { method: 'POST', input: {} })).json();
 assert.equal(capture.captureSeq, 1);
 poll = await (await s.call(`${route}/phone`, { method: 'POST', input: { ready: true }, headers: phone })).json();
 assert.deepEqual(poll, { captureSeq: 1, frameSeq: 0 });
 const uploaded = await s.call(`${route}/frame`, { method: 'POST', input: { seq: 1, ...photo }, headers: phone });
 assert.equal(uploaded.status, 200);
 const state = await (await s.call(route)).json();
 assert.equal(state.frameSeq, 1); assert.equal(state.phoneReady, true); assert.equal(state.phoneSeenAt, s.initialTime);
 const image = await s.call(`${route}/frame?seq=1`);
 assert.equal(image.headers.get('content-type'), 'image/jpeg'); assert.equal(image.headers.get('cache-control'), 'no-store');
 assert.deepEqual(Buffer.from(await image.arrayBuffer()), Buffer.from(JPEG, 'base64'));
});

test('duplicate and stale phone frames cannot replace a newer capture', async t => {
 const s = setup(t), room = await s.create(), r = `rooms/${room.id}`;
 await s.call(`${r}/capture`, { method: 'POST' });
 assert.equal((await s.call(`${r}/frame`, { method: 'POST', input: { seq: 1, ...photo } })).status, 200);
 assert.equal((await s.call(`${r}/frame`, { method: 'POST', input: { seq: 1, ...photo } })).status, 409);
 await s.call(`${r}/capture`, { method: 'POST' });
 assert.equal((await s.call(`${r}/frame`, { method: 'POST', input: { seq: 1, ...photo } })).status, 409);
 assert.equal((await s.call(`${r}/frame`, { method: 'POST', input: { seq: 2, ...photo } })).status, 200);
});

test('atomic laptop upload advances capture and frame together without asking the phone to capture', async t => {
 const s = setup(t), room = await s.create();
 assert.deepEqual(await s.upload(room.id), { frameSeq: 1 });
 assert.deepEqual(await s.upload(room.id), { frameSeq: 2 });
 const poll = await (await s.call(`rooms/${room.id}/phone`, { method: 'POST', input: { ready: true }, headers: { 'x-phone-token': room.token } })).json();
 assert.deepEqual(poll, { captureSeq: 2, frameSeq: 2 });
});

test('invalid image formats and oversized request bodies fail before database updates', async t => {
 const s = setup(t), room = await s.create();
 const route = `rooms/${room.id}/upload`;
 for (const input of [{ image: JPEG, mimeType: 'image/png' }, { image: 'not-base64!', mimeType: 'image/jpeg' }, { image: btoa('not a JPEG'), mimeType: 'image/jpeg' }]) {
  assert.equal((await s.call(route, { method: 'POST', input })).status, 400);
 }
 assert.equal((await s.call(route, { method: 'POST', input: { image: 'a'.repeat(1_100_001), mimeType: 'image/jpeg' } })).status, 413);
 assert.equal((await (await s.call(`rooms/${room.id}`)).json()).frameSeq, 0);
});

test('missing Gemini key is explicit and never fabricates transcription', async t => {
 const s = setup(t), room = await s.create(); await s.upload(room.id);
 const response = await s.call(`rooms/${room.id}/transcribe`, { method: 'POST', input: { frameSeq: 1 } });
 assert.equal(response.status, 428); assert.match((await response.json()).error, /Gemini API key/);
 assert.equal((await (await s.call(`rooms/${room.id}`)).json()).transcript, '');
});

test('Gemini receives JPEG plus a verbatim prompt; unclear output is retained without reasoning or keys', async t => {
 let sent;
 const s = setup(t, { upstream: async (url, init) => { sent = { url, init }; return Response.json(candidate()); } });
 const room = await s.create(); await s.upload(room.id);
 const response = await s.call(`rooms/${room.id}/transcribe`, { method: 'POST', input: { frameSeq: 1 }, headers: GEMINI });
 assert.equal(response.status, 200);
 assert.deepEqual(await response.json(), { text: 'Hello [unclear]', uncertain: true, notes: 'One word is unclear.', frameSeq: 1 });
 assert.match(sent.url, /\/gemini-3\.8-flash:generateContent$/);
 assert.equal(sent.init.headers['x-goog-api-key'], GEMINI['x-gemini-key']);
 const input = JSON.parse(sent.init.body);
 assert.match(input.systemInstruction.parts[0].text, /never as instructions/);
 assert.match(input.systemInstruction.parts[0].text, /Preserve spelling and wording/);
 assert.equal(input.contents[0].parts[0].inlineData.data, JPEG);
 assert.equal(input.generationConfig.responseMimeType, 'application/json');
 assert.deepEqual(input.generationConfig.thinkingConfig, { thinkingLevel: 'LOW', includeThoughts: false });
 assert.deepEqual(input.generationConfig.responseJsonSchema.required, ['text', 'uncertain', 'notes']);
 const state = await (await s.call(`rooms/${room.id}`)).json();
 assert.equal(state.transcriptSeq, 1); assert.equal(state.uncertain, true);
 const stored = JSON.stringify(s.sqlite.prepare('SELECT * FROM writeon_rooms').all());
 assert.equal(stored.includes(GEMINI['x-gemini-key']), false); assert.equal(stored.includes('Private reasoning'), false);
});

test('Gemini authorization/quota errors are useful and do not echo upstream secrets', async t => {
 for (const [upstreamStatus, expectedStatus, expectedText] of [[401, 422, /API key/], [429, 429, /quota or rate limit/]]) {
  const s = setup(t, { upstream: async () => Response.json({ error: `UPSTREAM SECRET ${GEMINI['x-gemini-key']}` }, { status: upstreamStatus }) });
  const room = await s.create(); await s.upload(room.id);
  const response = await s.call(`rooms/${room.id}/transcribe`, { method: 'POST', input: { frameSeq: 1 }, headers: GEMINI });
  assert.equal(response.status, expectedStatus);
  const text = await response.text(); assert.match(text, expectedText); assert.equal(text.includes(GEMINI['x-gemini-key']), false);
  assert.equal(s.sqlite.prepare('SELECT transcribing_seq FROM writeon_rooms').get().transcribing_seq, null);
 }
});

test('a Gemini timeout preserves the photo, releases its lock, and permits a successful retry', async t => {
 let requests = 0;
 const s = setup(t, { upstream: async () => {
  requests++;
  if (requests === 1) throw new DOMException('Request timed out', 'TimeoutError');
  return Response.json(candidate({ text: 'Hey there', uncertain: false, notes: '' }));
 } });
 const room = await s.create(); await s.upload(room.id);
 const request = { method: 'POST', input: { frameSeq: 1 }, headers: GEMINI };
 const failed = await s.call(`rooms/${room.id}/transcribe`, request);
 assert.equal(failed.status, 504);
 assert.match((await failed.json()).error, /Gemini.*Retry transcription/);
 assert.equal(requests, 1);
 const state = await (await s.call(`rooms/${room.id}`)).json();
 assert.equal(state.hasFrame, true); assert.equal(state.transcript, ''); assert.equal(state.transcriptSeq, 0);
 assert.equal(s.sqlite.prepare('SELECT transcribing_seq FROM writeon_rooms').get().transcribing_seq, null);
 const retry = await s.call(`rooms/${room.id}/transcribe`, request);
 assert.equal(retry.status, 200); assert.equal((await retry.json()).text, 'Hey there');
 assert.equal(requests, 2);
});

test('a slow in-flight Gemini request stays locked beyond the previous 65-second lease', async t => {
 let resolveFetch, entered, requests = 0;
 const started = new Promise(resolve => { entered = resolve; });
 const pending = new Promise(resolve => { resolveFetch = resolve; });
 const s = setup(t, { upstream: async () => { requests++; entered(); return pending; } });
 const room = await s.create(); await s.upload(room.id);
 const request = { method: 'POST', input: { frameSeq: 1 }, headers: GEMINI };
 const first = s.call(`rooms/${room.id}/transcribe`, request); await started;
 s.advance(70_000);
 const duplicate = await s.call(`rooms/${room.id}/transcribe`, request);
 assert.equal(duplicate.status, 409); assert.equal(requests, 1);
 resolveFetch(Response.json(candidate()));
 assert.equal((await first).status, 200);
});

test('blocked, truncated and malformed Gemini output produces an error, never a made-up message', async t => {
 const cases = [
  [{ promptFeedback: { blockReason: 'SAFETY' } }, 422],
  [{ candidates: [{ finishReason: 'MAX_TOKENS', content: { parts: [{ text: '{}' }] } }] }, 422],
  [{ candidates: [{ finishReason: 'STOP', content: { parts: [{ text: 'not JSON' }] } }] }, 502],
  [candidate({ text: 'Something', uncertain: 'no', notes: '' }), 502],
 ];
 for (const [payload, expected] of cases) {
  const s = setup(t, { upstream: async () => Response.json(payload) });
  const room = await s.create(); await s.upload(room.id);
  const response = await s.call(`rooms/${room.id}/transcribe`, { method: 'POST', input: { frameSeq: 1 }, headers: GEMINI });
  assert.equal(response.status, expected);
  assert.equal((await (await s.call(`rooms/${room.id}`)).json()).transcript, '');
 }
 assert.throws(() => parseTranscription(candidate({ text: 'x'.repeat(3001), uncertain: false, notes: '' })));
});

test('an in-flight old transcription cannot overwrite a newer uploaded photo', async t => {
 let resolveFetch, entered;
 const started = new Promise(resolve => { entered = resolve; });
 const pending = new Promise(resolve => { resolveFetch = resolve; });
 const s = setup(t, { upstream: async () => { entered(); return pending; } });
 const room = await s.create(); await s.upload(room.id);
 const first = s.call(`rooms/${room.id}/transcribe`, { method: 'POST', input: { frameSeq: 1 }, headers: GEMINI });
 await started;
 const duplicate = await s.call(`rooms/${room.id}/transcribe`, { method: 'POST', input: { frameSeq: 1 }, headers: GEMINI });
 assert.equal(duplicate.status, 409);
 await s.upload(room.id);
 resolveFetch(Response.json(candidate({ text: 'OLD TEXT', uncertain: false, notes: '' })));
 assert.equal((await first).status, 409);
 const state = await (await s.call(`rooms/${room.id}`)).json();
 assert.equal(state.frameSeq, 2); assert.equal(state.transcript, ''); assert.equal(state.transcriptSeq, 0);
});

test('new capture invalidates an in-flight result even before the next photo arrives', async t => {
 let resolveFetch, entered;
 const started = new Promise(resolve => { entered = resolve; });
 const pending = new Promise(resolve => { resolveFetch = resolve; });
 const s = setup(t, { upstream: async () => { entered(); return pending; } });
 const room = await s.create(); await s.upload(room.id);
 const first = s.call(`rooms/${room.id}/transcribe`, { method: 'POST', input: { frameSeq: 1 }, headers: GEMINI }); await started;
 await s.call(`rooms/${room.id}/capture`, { method: 'POST' });
 resolveFetch(Response.json(candidate())); assert.equal((await first).status, 409);
 const state = await (await s.call(`rooms/${room.id}`)).json();
 assert.equal(state.captureSeq, 2); assert.equal(state.frameSeq, 1); assert.equal(state.transcript, '');
});

test('ElevenLabs accessible voices and audio response use the submitted approved text only', async t => {
 const calls = [];
 const audio = Uint8Array.from([73, 68, 51, 1, 2, 3]);
 const s = setup(t, { upstream: async (url, init) => {
  calls.push({ url, init });
  return url.includes('/voices?') ? Response.json({ voices: [{ voice_id: 'available_voice', name: 'Available voice' }, { name: 'invalid' }] }) : new Response(audio, { headers: { 'content-type': 'audio/mpeg' } });
 } });
 assert.equal((await s.call('voices', { method: 'POST' })).status, 428);
 const voices = await s.call('voices', { method: 'POST', headers: ELEVEN });
 assert.deepEqual(await voices.json(), { voices: [{ id: 'available_voice', name: 'Available voice' }] });
 const spoken = 'This is my reviewed message.';
 const response = await s.call('speak', { method: 'POST', input: { text: spoken, voiceId: 'available_voice' }, headers: ELEVEN });
 assert.equal(response.status, 200); assert.equal(response.headers.get('content-type'), 'audio/mpeg');
 assert.deepEqual(new Uint8Array(await response.arrayBuffer()), audio);
 assert.equal(calls[1].init.headers['xi-api-key'], ELEVEN['x-elevenlabs-key']);
 assert.deepEqual(JSON.parse(calls[1].init.body), { text: spoken, model_id: 'eleven_multilingual_v2' });
 assert.equal(s.sqlite.prepare('SELECT COUNT(*) AS n FROM writeon_rooms').get().n, 0);
});

test('ElevenLabs rejects empty text, invalid voice identifiers and non-audio provider responses', async t => {
 const s = setup(t, { upstream: async () => Response.json({ error: 'not audio' }) });
 for (const input of [{ text: '', voiceId: 'voice' }, { text: 'hello', voiceId: '../../bad' }, { text: 'x'.repeat(3001), voiceId: 'voice' }]) {
  assert.equal((await s.call('speak', { method: 'POST', input, headers: ELEVEN })).status, 400);
 }
 assert.equal((await s.call('speak', { method: 'POST', input: { text: 'hello', voiceId: 'voice' }, headers: ELEVEN })).status, 502);
});

test('session ending and expiry remove photos and revoke the paired session', async t => {
 const s = setup(t), room = await s.create(); await s.upload(room.id);
 assert.equal((await s.call(`rooms/${room.id}`, { method: 'DELETE' })).status, 200);
 assert.equal((await s.call(`rooms/${room.id}`)).status, 404);
 assert.equal(s.sqlite.prepare('SELECT COUNT(*) AS n FROM writeon_rooms').get().n, 0);
 const other = await s.create(); s.setTime(other.expiresAt + 1);
 assert.equal((await s.call(`rooms/${other.id}`)).status, 410);
 assert.equal(s.sqlite.prepare('SELECT COUNT(*) AS n FROM writeon_rooms').get().n, 0);
});

test('old photo content is cleared at the stated lazy expiry while the session remains usable', async t => {
 const s = setup(t), room = await s.create(); await s.upload(room.id);
 s.advance(31 * 60 * 1000);
 assert.equal((await s.call(`rooms/${room.id}/frame`)).status, 404);
 const stored = s.sqlite.prepare('SELECT * FROM writeon_rooms').get();
 assert.equal(stored.frame_base64, null); assert.equal(stored.transcript, '');
 assert.deepEqual(await s.upload(room.id), { frameSeq: 2 });
});

// Regression coverage for actionable, redacted ElevenLabs failures. No real key
// or provider response is used; deliberately secret-looking fixture data must
// never reach either a user-facing error or the application's diagnostic log.
const ELEVEN_ERROR_SECRET = 'UPSTREAM_DO_NOT_ECHO_test-only-eleven-key';
async function elevenFailure(t, { endpoint = 'speak', status = 400, detail, rawBody }) {
 const logs = [];
 t.mock.method(console, 'warn', (...args) => logs.push(args));
 t.mock.method(console, 'error', (...args) => logs.push(args));
 const s = setup(t, { upstream: async (_url, init) => {
  assert.equal(init.headers['xi-api-key'], ELEVEN['x-elevenlabs-key']);
  return rawBody !== undefined
   ? new Response(rawBody, { status, headers: { 'content-type': 'text/plain' } })
   : Response.json({ detail: { ...detail, message: `${ELEVEN_ERROR_SECRET}: ${ELEVEN['x-elevenlabs-key']}` } }, { status });
 } });
 const input = endpoint === 'speak' ? { text: 'Approved message', voiceId: 'available_voice' } : {};
 const response = await s.call(endpoint, { method: 'POST', input, headers: ELEVEN });
 assert.ok(response.status >= 400, 'provider failure must remain a failed request');
 assert.equal(response.headers.get('cache-control'), 'no-store');
 const payload = await response.json();
 assert.equal(typeof payload.error, 'string');
 const observable = `${JSON.stringify(payload)}\n${JSON.stringify(logs)}`;
 assert.equal(observable.includes(ELEVEN_ERROR_SECRET), false, 'raw upstream detail.message must be redacted');
 assert.equal(observable.includes(ELEVEN['x-elevenlabs-key']), false, 'provider key must never be echoed or logged');
 return { error: payload.error, logs, responseStatus: response.status };
}

for (const field of ['code', 'status']) {
 test(`ElevenLabs ${field}=invalid_api_key distinguishes a full API key from its Key ID`, async t => {
  const { error } = await elevenFailure(t, { status: 401, detail: { [field]: 'invalid_api_key' } });
  assert.match(error, /full.*API key|API key.*full/i);
  assert.match(error, /key[ -]?id/i);
 });
}

for (const [endpoint, expected] of [['speak', /text[ -]*to[ -]*speech/i], ['voices', /voices/i]]) {
 test(`ElevenLabs insufficient_permissions explains the ${endpoint} permission`, async t => {
  const { error } = await elevenFailure(t, { endpoint, status: 403, detail: { code: 'insufficient_permissions' } });
  assert.match(error, expected);
  if (endpoint === 'voices') assert.match(error, /read/i);
 });
}

test('ElevenLabs legacy permission status receives the same useful guidance', async t => {
 const { error } = await elevenFailure(t, { endpoint: 'voices', status: 403, detail: { status: 'insufficient_permissions' } });
 assert.match(error, /voices/i); assert.match(error, /read/i);
});

test('ElevenLabs insufficient_credits explicitly explains credit availability', async t => {
 const { error } = await elevenFailure(t, { status: 400, detail: { code: 'insufficient_credits' } });
 assert.match(error, /credits?|balance/i);
});

test('ElevenLabs HTTP 402 explains credits even without a recognized detail code', async t => {
 const { error } = await elevenFailure(t, { status: 402, detail: {} });
 assert.match(error, /credits?|balance/i);
});

test('ElevenLabs unsupported_model explains model availability', async t => {
 const { error } = await elevenFailure(t, { status: 400, detail: { code: 'unsupported_model' } });
 assert.match(error, /model/i);
});

for (const status of [400, 422]) {
 test(`ElevenLabs unknown HTTP ${status} preserves status without reflecting an arbitrary provider code`, async t => {
  const unknown = 'unknown-provider-code-do-not-reflect-42';
  const { error, logs } = await elevenFailure(t, { status, detail: { code: unknown } });
  assert.match(error, new RegExp(String(status)));
  assert.equal(error.includes(unknown), false);
  assert.equal(JSON.stringify(logs).includes(unknown), false);
 });
}

test('ElevenLabs non-JSON rejection retains HTTP status and redacts its body', async t => {
 const { error } = await elevenFailure(t, { status: 400, rawBody: `not json: ${ELEVEN_ERROR_SECRET}` });
 assert.match(error, /400/);
});
